<?php require 'config.php'; role_required(['admin']); ensure_app_schema(); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();foreach(['system_name','approval_levels'] as $k)db()->prepare("REPLACE INTO app_settings(setting_key,setting_value) VALUES(?,?)")->execute([$k,trim($_POST[$k])]);flash('success','บันทึกการตั้งค่าแล้ว');redirect('settings.php');}$set=db()->query("SELECT setting_key,setting_value FROM app_settings")->fetchAll(PDO::FETCH_KEY_PAIR);$users=db()->query("SELECT id,name,username,role_code,department,active FROM users ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="th"><head><?php include 'partials/head.php';?></head><body><?php include 'partials/nav.php';?><main class="container"><h2>ตั้งค่าระบบ</h2><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>ชื่อระบบ</label><input name="system_name" value="<?=e($set['system_name']??'Material Flow')?>"></div><div class="field"><label>จำนวนขั้นตอนอนุมัติ</label><input name="approval_levels" type="number" min="1" max="10" value="<?=e($set['approval_levels']??3)?>"></div><button>บันทึก</button></form></div><div class="panel"><h3>ผู้ใช้งาน</h3><table class="table"><tr><th>ชื่อ</th><th>Username</th><th>สิทธิ์</th><th>แผนก</th><th>สถานะ</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['username'])?></td><td><?=e($u['role_code'])?></td><td><?=e($u['department'])?></td><td><?=$u['active']?'ใช้งาน':'ปิดใช้งาน'?></td></tr><?php endforeach;?></table></div></main></div></div></body></html>
